mapper.select:
SELECT * FROM payment_transaction
WHERE provider = #{provider}
  AND provider_transaction_no = #{providerTransactionNo}
  AND deleted = FALSE

mapper.update:
UPDATE payment_transaction SET status = 'SUCCEEDED', provider_amount = #{amount}, paid_at = #{paidAt},
    version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id} AND provider = 'INTERNAL_BALANCE' AND status = 'PENDING' AND deleted = FALSE

mapper.select:
SELECT * FROM payment_transaction
WHERE provider = #{provider}
  AND status = 'SUCCEEDED'
  AND paid_at >= #{startAt}
  AND paid_at < #{endAt}
  AND deleted = FALSE
ORDER BY id

SELECT * FROM payment_transaction
WHERE provider = #{provider}
  AND created_at >= #{startAt}
  AND created_at < #{endAt}
  AND deleted = FALSE
ORDER BY id
